SELECT t.TABLE_SCHEMA,t.TABLE_NAME,t.ROW_COUNT,t.LAST_ALTERED,ARRAY_AGG(OBJECT_CONSTRUCT('name',c.COLUMN_NAME,'type',c.DATA_TYPE)) WITHIN GROUP (ORDER BY c.ORDINAL_POSITION) AS COLUMNS FROM VECTOR_RESEARCH.INFORMATION_SCHEMA.TABLES t JOIN VECTOR_RESEARCH.INFORMATION_SCHEMA.COLUMNS c ON t.TABLE_CATALOG=c.TABLE_CATALOG AND t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE t.TABLE_SCHEMA <> 'INFORMATION_SCHEMA' GROUP BY 1,2,3,4 ORDER BY 1,2
